// Rappels du mois pour l'offre Visibilité Google. La liste des clients se tient ici, dans n8n (jamais dans le dépôt).
// Le 25 : demander les infos du mois. Le 28 : envoyer les brouillons à valider. Le 3 : envoyer le rapport.
const CLIENTS = [
  // { commerce: 'Nom du commerce', prenom: 'Prénom', canal: 'SMS' }   ← une ligne par client abonné
];
const jour = Number(($input.first().json.jour) ?? new Date().getDate());
const etapes = {
  25: { titre: 'Infos du mois à demander', quoi: 'message 1 de visibilite-google/prompts/3-point-mensuel.md' },
  28: { titre: 'Brouillons à faire valider', quoi: 'preparer ou rediger, controler, puis message 2' },
  3: { titre: 'Rapports à envoyer', quoi: 'rapport.html relu, puis message 3' }
};
const e = etapes[jour];
if (!e) return [];
const lignes = CLIENTS.length ? CLIENTS.map((c) => `- ${c.commerce} (${c.prenom}, ${c.canal})`) : ['- aucun client dans la liste (nœud « Rappels du mois »)'];
return [{ json: { texte: `Visibilité Google : ${e.titre}\n${lignes.join('\n')}\n\nÀ faire : ${e.quoi}.` } }];
